using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;
using System.Text.Json;

// ── Tool implementations ────────────────────────────────────────────────────

/// <summary>Tools the research agent can invoke during its investigation loop.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    [Description("Search the web for a query and return a list of result snippets. Use this to gather information on a research topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍  Searching: {query}");

        // Use DuckDuckGo instant-answer API (no key required).
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await s_http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / AbstractText
            var abs = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
                results.Add($"[Summary] {abs}");

            // RelatedTopics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add($"• {text}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : "No results found. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key facts, findings, or quotes discovered during research.")]
    public static string SaveNote(
        [Description("The note text to save")] string note)
    {
        s_notes.Add(note);
        Console.WriteLine($"  📝  Note #{s_notes.Count} saved");
        return $"Note saved (total notes: {s_notes.Count}).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        var lines = s_notes.Select((n, i) => $"{i + 1}. {n}");
        return string.Join("\n", lines);
    }
}

// ── Main ────────────────────────────────────────────────────────────────────

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software engineering";

Console.WriteLine("Research Agent Starting...");
Console.WriteLine($"📚 Topic: {topic}\n");

// Build the chat client with automatic function-calling support.
var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AIFunctionFactory[]{ }; // placeholder – we register below

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ],
    Temperature = 0.3f,
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a thorough research agent. Your goal is to research the given topic
        by searching the web multiple times with varied queries, saving important
        findings as notes, and finally producing a well-structured summary.

        Workflow:
        1. Search the web with 2-3 different queries to explore the topic from
           multiple angles.
        2. After each search, save the most important facts as notes using SaveNote.
        3. When you have gathered enough information, call GetNotes to review
           everything, then write a final structured summary with sections and
           key takeaways.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}"),
};

// Agent loop – keep going until the model produces a final answer with no tool calls.
Console.WriteLine("─── Agent working ───────────────────────────────────────\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n─── Research Summary ────────────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n─────────────────────────────────────────────────────────");

